    // Builds the log-in dialog data with buttons ordered for the current platform.
    logInDialogData() {
      let appleButton = {
          authProviderId: authProviders.APPLE,
          title: translate(phrases.log_in_continue_with_apple),
          icon: icons.LOGIN_APPLE,
        },
        googleButton = {
          authProviderId: authProviders.GOOGLE,
          title: translate(phrases.log_in_continue_with_google),
          icon: icons.LOGIN_GOOGLE,
        },
        twitterButton = {
          authProviderId: authProviders.TWITTER,
          title: translate(phrases.log_in_continue_with_twitter),
          icon: icons.LOGIN_TWITTER,
        },
        emailButton = {
          authProviderId: authProviders.EMAIL_PASSWORD,
          title: translate(phrases.log_in_continue_with_email),
          icon: icons.LOGIN_EMAIL,
        },
        buttons = [];
      switch (dataStoreShared.platform) {
        case platform.IOS:
          (this.osMajorVersion >= 13 && buttons.push(appleButton), buttons.push(googleButton, twitterButton, emailButton));
          break;
        case platform.ANDROID:
          buttons.push(googleButton, appleButton, twitterButton, emailButton);
      }
      return { authenticationData: this.auth.authenticationData(), buttons };
    }
