    sayInCurrentScreen(message, isLocalized) {
      switch (this.activeGameScreen()) {
        case gameScreens.PLAY:
          this.playScreenController.sayInCurrentScreen(message, isLocalized);
          break;
        case gameScreens.TRAIN:
          this.trainScreenController.sayInCurrentScreen(message, isLocalized);
          break;
        case gameScreens.LESSON:
          this.lessonScreenController.sayInCurrentScreen(message, isLocalized);
      }
    }
